package io.github.astelev.around_planet.space;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class MoonAppearanceTest {
 @Test void allSurfaceObserversReconstructTheSameOrbitalMoon(){var sys=new CelestialSystem(20000,4e9,12345);var planet=new PlanetGeometry(20000*Math.PI,10000*Math.PI);for(double x:new double[]{0,10000,-50000})for(double day:new double[]{0,6000,18000}){var spin=PlanetSpin.at(day,true);var world=new SpaceVector(x,1700,5000);double tick=9000.5;var a=MoonAppearance.at(sys,planet,spin,world,tick);var absolute=spin.frame(planet,world.x(),world.z()).toCosmic(a.center()).add(spin.position(planet,world.x(),world.y(),world.z()));assertTrue(absolute.subtract(sys.moonSeconds(tick/20).position()).length()<1e-7);}}
 @Test void angularSizeUsesRealObserverDistanceAndAltitude(){var sys=new CelestialSystem(20000,4e9,0);var planet=new PlanetGeometry(20000*Math.PI,10000*Math.PI);var spin=PlanetSpin.at(6000,true);var low=MoonAppearance.at(sys,planet,spin,new SpaceVector(planet.halfX()/2,100,0),0);var high=MoonAppearance.at(sys,planet,spin,new SpaceVector(planet.halfX()/2,10000,0),0);assertEquals(0,low.center().x(),1e-7);assertEquals(sys.distance()-planet.radius()-100,low.center().y(),1e-7);assertEquals(Math.asin(sys.moonRadius()/(sys.distance()-planet.radius()-100)),low.angularRadius(),1e-10);assertTrue(high.angularRadius()>low.angularRadius());var opposite=MoonAppearance.at(sys,planet,spin,new SpaceVector(-planet.halfX()/2,100,0),0);assertTrue(opposite.center().y()<0);}
 @Test void timeWarpUsesSameEphemerisAsTheMap(){var sys=new CelestialSystem(20000,4e9,1000);var planet=new PlanetGeometry(20000*Math.PI,10000*Math.PI);var spin=PlanetSpin.at(18000,true);var p=new SpaceVector(5000,500,3000);assertEquals(MoonAppearance.at(sys,planet,spin,p,6000),MoonAppearance.at(sys.warp(5000),planet,spin,p,1000));}
}
